import React, { useState } from 'react';

// Données des chapitres pour la démo devant le jury
const chapitresCours = [
  { id: 1, titre: "01. Introduction aux vulnérabilités réseaux", duree: "12:45", valide: true },
  { id: 2, titre: "02. Analyse de paquets avec Wireshark", duree: "24:15", valide: true },
  { id: 3, titre: "03. Exploitation pratique (Laboratoire)", duree: "45:00", valide: false },
  { id: 4, titre: "04. Quiz de validation des compétences", duree: "10:00", valide: false },
];

export default function Dashboard({ onLogout }) {
  const [chapitreActif, setChapitreActif] = useState(chapitresCours[0]);

  return (
    <div className="bg-[#030712] text-gray-100 min-h-screen flex flex-col font-sans">
      
      {/* HEADER DU TERMINAL ÉTUDIANT */}
      <header className="border-b border-slate-800 bg-[#0f172a] px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-3 h-3 rounded-full bg-emerald-500 animate-pulse"></div>
          <span className="text-sm font-mono text-emerald-400">SESSION_ACTIVE // ÉTUDIANT_CONNECTÉ</span>
        </div>
        <button 
          onClick={onLogout}
          className="text-xs bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 px-3 py-1.5 rounded-md transition-colors"
        >
          Déconnexion [Exit]
        </button>
      </header>

      <div className="flex-1 flex flex-col md:flex-row">
        
        {/* 📑 BARRE LATÉRALE : LES CHAPITRES */}
        <aside className="w-full md:w-80 bg-[#0f172a]/50 border-r border-slate-800 p-4 flex flex-col gap-2">
          <h3 className="text-xs font-mono uppercase tracking-wider text-cyan-400 px-2 mb-2">
            Plan du Module
          </h3>
          <div className="space-y-1">
            {chapitresCours.map((chap) => (
              <button
                key={chap.id}
                onClick={() => setChapitreActif(chap)}
                className={`w-full text-left p-3 rounded-xl transition-all flex justify-between items-center text-sm ${
                  chapitreActif.id === chap.id 
                    ? 'bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 font-bold' 
                    : 'hover:bg-slate-800/50 text-gray-400'
                }`}
              >
                <span className="truncate pr-2">{chap.titre}</span>
                <span className="text-xs font-mono opacity-60 shrink-0">{chap.duree}</span>
              </button>
            ))}
          </div>
        </aside>

        {/* 📺 ZONE CENTRALE : LECTEUR ET LABO */}
        <main className="flex-1 p-6 md:p-8 flex flex-col gap-6">
          <div className="border border-slate-800 bg-[#0f172a] rounded-2xl p-6">
            <span className="text-xs font-mono text-cyan-400 uppercase tracking-widest block mb-1">
              Chapitre en cours
            </span>
            <h2 className="text-2xl font-black text-white mb-4">
              {chapitreActif.titre}
            </h2>
            
            {/* Simulation de l'écran vidéo ou du labo */}
            <div className="aspect-video w-full bg-[#030712] rounded-xl border border-slate-800 flex flex-col items-center justify-center p-4 relative overflow-hidden group">
              <div className="absolute inset-0 bg-gradient-to-t from-cyan-950/20 to-transparent pointer-events-none"></div>
              <div className="w-16 h-16 rounded-full bg-cyan-400 text-slate-950 flex items-center justify-center font-bold text-xl cursor-pointer shadow-lg shadow-cyan-400/20 transform group-hover:scale-110 transition-transform">
                ▶
              </div>
              <p className="text-xs font-mono text-gray-500 mt-4">
                [Flux vidéo de démonstration de cyberdéfense sécurisé]
              </p>
            </div>
          </div>

          {/* SECTION DU LABO PRATIQUE */}
          <div className="border border-slate-800/60 bg-[#0f172a]/30 rounded-2xl p-6">
            <h4 className="text-sm font-bold text-white mb-2">Instructions de validation</h4>
            <p className="text-gray-400 text-sm leading-relaxed">
              Pour valider ce module, suivez la vidéo guidée ci-dessus et reproduisez l'attaque dans votre environnement virtuel local. Soumettez ensuite le flag récupéré lors du quiz.
            </p>
          </div>
        </main>

      </div>
    </div>
  );
}
